<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue';
import { business, managedClubs, refreshBusiness } from '../prototype/business';
import { activityState, managedActivities, refreshActivities, saveDraft, publishActivity, editActivity, cancelManagedActivity, activityTime, type Draft, type Activity } from './activities';
import CommunityCheckInPanel from './CommunityCheckInPanel.vue';
import CommunityDialog from './CommunityDialog.vue';
import { planningState, generatePlan, preparePlanDraft, confirmPlanDraft, discardUnsentDraft } from './planning';
const showForm = ref(false), selected = ref<Activity>();
const editing = ref<Activity>(), cancelling = ref<Activity>(), cancelReason = ref('');
const form = ref<Draft>({ title: '', description: '', location: '', startTime: '', registrationDeadline: '', capacity: 30 });
const formError = ref(''), peopleFor = ref<number>();
const requirement = ref(''), planForm = ref(false), confirmingPlan = ref(false);
const club = computed(() => managedClubs.value.find(c => c.backendId === business.managedClubId));
onMounted(refreshActivities);
watch([() => business.user?.id, () => business.user?.role, () => business.managedClubId], () => { peopleFor.value = undefined; selected.value = undefined; showForm.value = false; editing.value = undefined; cancelling.value = undefined; cancelReason.value = ''; form.value = emptyForm(); }, { flush: 'sync' });
watch([() => business.user?.id, () => business.managedClubId], refreshActivities);
watch([() => business.user?.id, () => business.managedClubId], () => { requirement.value = ''; planForm.value = false; confirmingPlan.value = false; }, { flush: 'sync' });
async function plan() {
  const proposal = await generatePlan(requirement.value);
  if (!proposal) return;
  editing.value = undefined; form.value = { ...emptyForm(), title: proposal.title, description: proposal.description }; showForm.value = true; planForm.value = true; formError.value = '';
}
function closePlan() { confirmingPlan.value = false; discardUnsentDraft(); }
async function confirmPlan() { if (await confirmPlanDraft()) { confirmingPlan.value = false; showForm.value = false; planForm.value = false; form.value = emptyForm(); } }
function emptyForm(): Draft { return { title: '', description: '', location: '', startTime: '', registrationDeadline: '', capacity: 30 }; }
function openForm() { formError.value = ''; activityState.writeError = ''; editing.value = undefined; planForm.value = false; form.value = emptyForm(); showForm.value = !showForm.value; }
function openEdit(activity: Activity) {
  editing.value = activity; planForm.value = false; formError.value = ''; activityState.writeError = '';
  form.value = { title: activity.title, description: activity.description, location: activity.location, startTime: activity.startTime, registrationDeadline: activity.registrationDeadline, capacity: activity.capacity }; showForm.value = true;
}
function canChange(activity: Activity) { return activity.status !== 'CANCELLED' && new Date(activity.startTime).getTime() > Date.now(); }
function askCancel(activity: Activity) { cancelling.value = activity; cancelReason.value = ''; activityState.writeError = ''; }
async function cancel() { if (cancelling.value && cancelReason.value.trim() && await cancelManagedActivity(cancelling.value.id, cancelReason.value.trim())) cancelling.value = undefined; }
async function save() {
  if (planForm.value && planningState.pending) { confirmingPlan.value = true; return; }
  formError.value = '';
  if (!form.value.title.trim() || !form.value.description.trim() || !form.value.location.trim()) { formError.value = '请填写活动名称、介绍和地点。'; return; }
  const deadline = new Date(form.value.registrationDeadline).getTime(), start = new Date(form.value.startTime).getTime();
  const unchangedDeadline = editing.value?.status === 'PUBLISHED' && editing.value.registrationDeadline === form.value.registrationDeadline;
  if (!Number.isFinite(deadline) || !Number.isFinite(start) || start <= Date.now() || deadline > start || (!unchangedDeadline && deadline <= Date.now())) { formError.value = '开始时间须在未来，截止不能晚于开始；修改截止时间时须晚于当前时间。'; return; }
  if (planForm.value) { if (preparePlanDraft(form.value)) confirmingPlan.value = true; return; }
  const userId = business.user?.id, clubId = business.managedClubId;
  const saved = editing.value ? await editActivity(editing.value.id, form.value) : clubId !== null && await saveDraft(clubId, form.value);
  if (saved && userId === business.user?.id && clubId === business.managedClubId) { showForm.value = false; editing.value = undefined; form.value = emptyForm(); }
}
function askPublish(activity: Activity) { activityState.writeError = ''; selected.value = activity; }
async function publish() { if (selected.value && await publishActivity(selected.value.id)) selected.value = undefined; }
function people(activity: Activity) { peopleFor.value = peopleFor.value === activity.id ? undefined : activity.id; }
</script>
<template><div class="community-directory"><div class="community-page-title"><h1>活动管理</h1><RouterLink to="/manage">返回工作台</RouterLink></div>
  <div v-if="business.user?.role !== 'MANAGER'" class="community-list-message"><h2>请使用社团负责人账号</h2><p>只能管理你负责社团的活动。</p><RouterLink to="/login" class="community-button">前往登录</RouterLink></div>
  <template v-else><div class="community-manager-toolbar"><label>管理社团<select v-model="business.managedClubId" :disabled="activityState.saving || business.loading" @change="refreshBusiness"><option v-for="item in managedClubs" :key="item.id" :value="item.backendId">{{ item.name }}</option></select></label><button v-if="club" class="community-button" :disabled="activityState.saving" @click="openForm">{{ showForm ? '收起表单' : '新建活动' }}</button></div>
    <p v-if="business.error" class="community-error" role="alert">{{ business.error }}</p>
    <section v-if="club" class="community-assistant-section" aria-labelledby="activity-plan-title"><h2 id="activity-plan-title">活动策划参考</h2><p>描述活动目标，助手只拟标题、介绍和简要流程，不预约场地、不设置经费、不直接保存或发布。也可以不用助手，直接新建活动。</p><form class="community-event-form" @submit.prevent="plan"><label>活动想法<textarea v-model="requirement" required maxlength="2000" rows="3" :disabled="planningState.loading || !!planningState.pending" placeholder="例如：给摄影新手办一次构图交流，包含作品分享和安全提醒" /></label><button class="community-button secondary" :disabled="planningState.loading || planningState.saving || !!planningState.pending">{{ planningState.loading ? '正在生成文案…' : '生成策划参考' }}</button></form><p v-if="planningState.proposal">{{ planningState.proposal.mode === 'LOCAL' ? '本地模板，未调用大模型。' : '模型生成的待审核文案。' }}请在下方修改，并补齐真实时间、地点和人数。</p><p v-if="planningState.error" class="community-error" role="alert">{{ planningState.error }}</p><p v-if="planningState.notice" role="status">{{ planningState.notice }}</p><button v-if="planningState.pending && !confirmingPlan" class="community-button secondary" @click="confirmingPlan = true">核对本次待保存草稿</button></section>
    <form v-if="showForm && club" class="community-event-form" @submit.prevent="save"><h2>{{ editing ? '编辑活动' : '新建活动草稿' }}</h2><p>{{ editing?.status === 'PUBLISHED' ? '已发布活动保存后对学生可见。有人报名时不能修改时间或地点，人数上限不能少于已报名人数。' : '草稿保存后不会对学生展示，需要再次确认发布。' }}</p><label>活动名称<input v-model="form.title" required maxlength="100" /></label><label>活动介绍<textarea v-model="form.description" required maxlength="2000" rows="4"></textarea></label><label>活动地点<input v-model="form.location" :disabled="!!editing && editing.enrolled > 0" required maxlength="200" placeholder="例如：学生中心 204" /></label><div class="community-form-columns"><label>活动开始时间<input v-model="form.startTime" :disabled="!!editing && editing.enrolled > 0" type="datetime-local" step="any" required /></label><label>报名截止时间<input v-model="form.registrationDeadline" type="datetime-local" step="any" required /></label></div><label>人数上限（1—500 人）<input v-model.number="form.capacity" type="number" required min="1" max="500" /></label><p v-if="formError || activityState.writeError" class="community-error" role="alert">{{ formError || activityState.writeError }}</p><button class="community-button" :disabled="activityState.saving">{{ activityState.saving ? '正在保存…' : editing ? '保存修改' : planForm ? '核对并保存草稿' : '保存草稿' }}</button></form>
    <div class="community-list-heading"><h2>{{ club?.name || '尚未分配管理社团' }}</h2><button class="community-text-link" :disabled="activityState.loading" @click="refreshActivities">刷新活动</button></div>
    <p v-if="activityState.error" class="community-error" role="alert">{{ activityState.error }}</p><p v-if="activityState.loading" class="community-list-loading">正在读取活动…</p>
    <template v-else-if="!activityState.error"><article v-for="activity in managedActivities" :key="activity.id" class="community-managed-event"><div class="community-club-title"><h3>{{ activity.title }}</h3><span class="community-recruiting">{{ activity.status === 'DRAFT' ? '草稿 · 学生不可见' : activity.status === 'CANCELLED' ? '已取消' : '已发布' }}</span></div><p>{{ activityTime(activity.startTime) }} · {{ activity.location }}</p><p>报名截止 {{ activityTime(activity.registrationDeadline) }} · {{ activity.enrolled }} / {{ activity.capacity }} 人</p><p v-if="activity.cancelReason">取消原因：{{ activity.cancelReason }}</p><div class="community-dialog-actions"><button v-if="canChange(activity)" class="community-text-link" :disabled="activityState.saving" @click="openEdit(activity)">编辑活动</button><button v-if="canChange(activity)" class="community-text-link" :disabled="activityState.saving" @click="askCancel(activity)">取消活动</button><button v-if="activity.status === 'DRAFT'" class="community-button secondary" :disabled="activityState.saving" @click="askPublish(activity)">确认发布</button><template v-else-if="activity.status === 'PUBLISHED'"><RouterLink :to="`/activities/${activity.id}`" class="community-text-link">活动详情</RouterLink><button class="community-text-link" :aria-expanded="peopleFor === activity.id" @click="people(activity)">{{ peopleFor === activity.id ? '收起签到与名单' : '签到与报名名单' }}</button></template></div><CommunityCheckInPanel v-if="peopleFor === activity.id" :activity-id="activity.id" /></article><div v-if="!managedActivities.length" class="community-list-message"><h3>暂无活动</h3><p>点击“新建活动”，填写内容并保存草稿。</p></div></template>
    <p class="community-list-disclosure">草稿、发布、报名和签到使用本地数据库 · 虚构账号与资料<br />地点直接填写，不包含场地预约；已发布活动取消后会保存原因并发送站内通知。预算与支出请进入<RouterLink to="/manage/finance" class="community-text-link">经费台账</RouterLink>；不包含学校级经费审批。</p>
  </template>
  <CommunityDialog v-if="confirmingPlan && planningState.pending" title="人工确认保存草稿" :busy="planningState.saving" @close="closePlan"><h3>{{ planningState.pending.body.title }}</h3><p class="plan-description">{{ planningState.pending.body.description }}</p><p>{{ activityTime(planningState.pending.body.startTime) }} · {{ planningState.pending.body.location }} · {{ planningState.pending.body.capacity }} 人</p><p>报名截止 {{ activityTime(planningState.pending.body.registrationDeadline) }}。请确认内容真实、安排可行。此操作仅保存草稿，不发布、不扣款。</p><p v-if="planningState.pending.attempted">已发送过本次确认。重试沿用相同编号与内容；成功后再从列表编辑。</p><p v-if="planningState.error" class="community-error" role="alert">{{ planningState.error }}</p><div class="community-dialog-actions"><button type="button" class="community-button secondary" :disabled="planningState.saving" @click="closePlan">{{ planningState.pending.attempted ? '返回核对列表' : '返回修改' }}</button><button type="button" class="community-button" :disabled="planningState.saving" @click="confirmPlan">{{ planningState.saving ? '正在保存…' : planningState.pending.attempted ? '按相同内容重试' : '确认保存草稿' }}</button></div></CommunityDialog>
  <CommunityDialog v-if="cancelling" title="确认取消活动" :busy="activityState.saving" @close="cancelling = undefined"><h3>{{ cancelling.title }}</h3><p>取消后停止报名并释放有效报名，向已报名学生发送站内通知。活动、取消原因与历史记录保留；已有人签到或活动已开始时不能取消。</p><form class="community-event-form" @submit.prevent="cancel"><label>取消原因<textarea v-model="cancelReason" required maxlength="300" rows="3" /></label><p v-if="activityState.writeError" class="community-error" role="alert">{{ activityState.writeError }}</p><div class="community-dialog-actions"><button type="button" class="community-button secondary" :disabled="activityState.saving" @click="cancelling = undefined">保留活动</button><button class="community-button" :disabled="activityState.saving || !cancelReason.trim()">{{ activityState.saving ? '正在取消…' : '确认取消活动' }}</button></div></form></CommunityDialog>
  <CommunityDialog v-if="selected" title="确认发布活动" :busy="activityState.saving" @close="selected = undefined"><h3>{{ selected.title }}</h3><p>{{ activityTime(selected.startTime) }} · {{ selected.location }}</p><p>报名截止 {{ activityTime(selected.registrationDeadline) }} · {{ selected.capacity }} 人</p><p>发布后，全校学生可查看并报名。请确认时间、地点和名额无误。</p><p v-if="activityState.writeError" class="community-error" role="alert">{{ activityState.writeError }}</p><div class="community-dialog-actions"><button class="community-button secondary" :disabled="activityState.saving" @click="selected = undefined">返回</button><button class="community-button" :disabled="activityState.saving" @click="publish">{{ activityState.saving ? '正在发布…' : '发布活动' }}</button></div></CommunityDialog>
</div></template>
<style scoped>.plan-description { white-space: pre-wrap; overflow-wrap: anywhere; }</style>
